@module masterMix  src=masterMix.lua  loc=144  mode=chunk  self=masterMix
@deps chrome, ctx

# Shapes
  @shape  masterMix = { segment = { id = 'master', render } }   -- one shared toolbar segment  @ 4

# Imports
  @require ImGui = 'imgui'  @ 6
      @reaper  reads GetMasterTrack + D_VOL + Track_GetPeakInfo(0/1 peak, 1024 loudness) + time_precise; writes via CSurf_OnVolumeChange  @ 3

# Private state
  @state colour = chrome.colour  @ 9
  @state masterMix = {}  @ 11
  @state WIDTH = 170  @ 13
  @state BAR_H = 8  @ 14
  @state HANDLE_W = 7  @ 15   -- grab handle width, px
  @state HANDLE_H = 11  @ 16   -- grab handle height, px
  @state METER_MIN = -60  @ 17
  @state METER_MAX = 6  @ 18
  @state ZERO_FRAC = (0 - METER_MIN) / (METER_MAX - METER_MIN)  @ 19   -- where 0 dB sits across the bar
  @state DETENT_DB = 0.7  @ 20   -- a drag snaps to unity within this band of 0 dB
  @state PEAK_SMOOTH = 0.5  @ 21   -- ~2-frame averaging on the bar fill (the raw peak is nervy)
  @state HOLD_TIME = 1.5  @ 22   -- seconds a peak is held before it releases to the current level
  @state suppressDrag = false  @ 70   -- a double-click reset holds off drag until the mouse releases
  @state peakL, peakR = 0, 0  @ 71   -- frame-averaged bar fills
  @state holdL, holdR = METER_MIN, METER_MIN  @ 72   -- held peak per channel, dB
  @state holdAtL, holdAtR = 0, 0  @ 73   -- time_precise() when each hold last latched

# Private functions
  @fn clamp01(v)  @ 24
  @fn px(v)  @ 25
  @fn ampToDb(a)  @ 26
  @fn dbFrac(db)  @ 27
  @fn loudnessDb(raw)  @ 31
      -- Channel 1024 returns loudness, but its scale is undocumented; treated as
      -- linear amplitude here. See docs/masterMix.md § Loudness scale.
  @fn volToFrac(vol)  @ 34-37
      -- REAPER's own fader taper (matches a track fader): frac 0..1 <-> dB <-> vol.
  @fn fracToDb(frac)  @ 38
  @fn dbToVol(db)  @ 39
  -- Crisp (non-AA) primitives: ReaImGui's AddLine/AddRect are anti-aliased with
  -- no per-call toggle, so axis-aligned filled rects stand in for 1px rules.
  @fn hrule(dl, x0, x1, y, col)  @ 44
  @fn vrule(dl, x, y0, y1, col)  @ 45
  @fn chip(dl, x, y0, y1, col)  @ 46
  @fn box(dl, x0, y0, x1, y1, col)  @ 47-50
  -- Meter bars
  @fn drawBar(dl, x, top, peak, holdDb, loudX)  @ 54-66
  -- Segment
  @fn holdPeak(heldDb, latchedAt, db, now)  @ 77-80
      -- Latch a higher peak and stamp the time; once HOLD_TIME elapses with nothing
      -- louder, release the hold to the current level.
  @fn render()  @ 82-140

# Uses (outbound edges)
  @use call    ImGui.CalcTextSize  @ render:133
  @use call    ImGui.DrawList_AddRectFilled  @ hrule:44 vrule:45 chip:46 drawBar:55,59,61 render:126,136
  @use call    ImGui.DrawList_AddText  @ render:138
  @use call    ImGui.GetCursorScreenPos  @ render:86
  @use call    ImGui.GetForegroundDrawList  @ render:134
  @use call    ImGui.GetFrameHeight  @ render:88
  @use call    ImGui.GetMousePos  @ render:98
  @use call    ImGui.GetWindowDrawList  @ render:89
  @use call    ImGui.InvisibleButton  @ render:92
  @use call    ImGui.IsItemActive  @ render:93
  @use call    ImGui.IsItemHovered  @ render:94
  @use call    ImGui.IsMouseDoubleClicked  @ render:94
  @use require imgui  @ <load>:6

# Calls (intra-file)
  @call ampToDb  @ loudnessDb:31 drawBar:56 render:111,112
  @call box  @ render:127,128,137
  @call chip  @ drawBar:65
  @call clamp01  @ dbFrac:27 volToFrac:36 render:99
  @call dbFrac  @ drawBar:56,65 render:106
  @call dbToVol  @ render:101
  @call drawBar  @ render:113,114
  @call fracToDb  @ render:99
  @call holdPeak  @ render:111,112
  @call hrule  @ box:48 render:118
  @call loudnessDb  @ render:105
  @call px  @ hrule:44 vrule:45 chip:46 render:87,120,135
  @call volToFrac  @ render:119,120
  @call vrule  @ box:49 drawBar:64 render:119

# Bindings (by name)
  @bind render  @ 142

# REAPER API surface
  @reaper DB2SLIDER
  @reaper GetMasterTrack
  @reaper CSurf_OnVolumeChange
  @reaper Track_GetPeakInfo
  @reaper time_precise
  @reaper GetMediaTrackInfo_Value

# Fields (r read / w write incl. constructor keys)
  @field r MouseButton_Left  @ render:94
  @field r chrome  @ 8
  @field r colour  @ 9
  @field r ctx  @ 8
  @field w id  @ 142
  @field w render  @ 142
  @field w segment  @ 142
